/** Every preset id, in catalogue order. */
export const FACE_PRESET_IDS = FACE_PRESETS.map(
  (p) => p.id,
) as readonly FacePreset[];

/** Every palette, in picker order, with its name. Every part of a Pebble is drawn in its own palette. */
export const FACE_PALETTES: readonly {
  id: FacePalette;
  name: string;
  dark?: true;
  neutral?: true;
  glass?: true;
}[] = [
  {
    id: "blue",
    name: "Blue",
  },
  {
    id: "violet",
    name: "Violet",
  },
  {
    id: "pink",
    name: "Pink",
  },
  {
    id: "orange",
    name: "Orange",
  },
  {
    id: "green",
    name: "Green",
  },
  {
    id: "teal",
    name: "Teal",
  },
  {
    id: "ink",
    name: "Ink",
    dark: true,
  },
  {
    id: "mist",
    name: "Mist",
    neutral: true,
  },
  {
    id: "glass",
    name: "Glass",
    neutral: true,
    glass: true,
  },
];

/** Every palette id, in picker order. */
export const FACE_PALETTE_IDS = FACE_PALETTES.map(
  (p) => p.id,
) as readonly FacePalette[];

/** A preset's definition by id. */
export function facePreset(id: FacePreset): FacePresetDef {
  return FACE_PRESETS.find((p) => p.id === id) ?? FACE_PRESETS[0]!;
}
